import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.BgSoyxN5.js";const u=JSON.parse('{"title":"Cookie Policy","description":"","frontmatter":{},"headers":[],"relativePath":"cookies.md","filePath":"cookies.md","lastUpdated":1783323835000}'),r={name:"cookies.md"};function s(n,e,l,c,d,p){return t(),a("div",null,e[0]||(e[0]=[i('<h1 id="cookie-policy" tabindex="-1">Cookie Policy <a class="header-anchor" href="#cookie-policy" aria-label="Permalink to &quot;Cookie Policy&quot;">​</a></h1><p><em>Last updated: 04 July 2026</em></p><p>This Cookie Policy explains how <strong>TickerForge</strong> (“we”, “us”, or “our”) uses cookies and similar tracking technologies on the <strong>ticker-forge.com</strong> website.</p><p>For information about how we collect, use, and protect your personal data, please also read our <a href="/privacy">Privacy Policy</a>.</p><hr><h2 id="_1-what-are-cookies" tabindex="-1">1. What Are Cookies? <a class="header-anchor" href="#_1-what-are-cookies" aria-label="Permalink to &quot;1. What Are Cookies?&quot;">​</a></h2><p>Cookies are small text files stored on your device (computer, tablet, or smartphone) when you visit a website.<br> They help websites remember your actions and preferences (such as login, language, or display settings) so you don’t have to re-enter them each time you return.</p><p>Cookies can also help us understand how visitors use our site so we can improve it.</p><hr><h2 id="_2-how-we-use-cookies" tabindex="-1">2. How We Use Cookies <a class="header-anchor" href="#_2-how-we-use-cookies" aria-label="Permalink to &quot;2. How We Use Cookies&quot;">​</a></h2><p>TickerForge uses cookies and similar technologies for the following purposes:</p><table tabindex="0"><thead><tr><th>Type of Cookie</th><th>Purpose</th><th>Examples</th></tr></thead><tbody><tr><td><strong>Essential Cookies</strong></td><td>Required for the site to function properly (e.g., navigation, security).</td><td>Session ID, CSRF token</td></tr><tr><td><strong>Analytics Cookies</strong></td><td>Help us understand how visitors use our site so we can improve usability and performance.</td><td>Google Analytics (GA4)</td></tr><tr><td><strong>Preference Cookies</strong></td><td>Remember your language, theme, or display settings.</td><td>Dark/light mode</td></tr><tr><td><strong>Marketing / Advertising Cookies</strong></td><td>Help us measure campaigns, understand product interest, and build remarketing audiences when permitted by your consent.</td><td>Meta Pixel, Google Ads / GA4 audiences</td></tr></tbody></table><p>We do <strong>not</strong> sell personal data. Optional analytics and advertising cookies are controlled by the consent choices shown on the website where applicable.</p><hr><h2 id="_3-third-party-cookies" tabindex="-1">3. Third-Party Cookies <a class="header-anchor" href="#_3-third-party-cookies" aria-label="Permalink to &quot;3. Third-Party Cookies&quot;">​</a></h2><p>Some cookies are set by third parties that provide analytics or social media integration.<br> These may include (depending on your settings):</p><ul><li><strong>Google Analytics (GA4)</strong> — to collect anonymous site-usage data.</li><li><strong>Google Ads / GA4 audiences</strong> — to support remarketing and campaign measurement where enabled.</li><li><strong>Meta Pixel / Meta Ads</strong> — to measure website events and build Meta Website Custom Audiences where enabled.</li><li><strong>Telegram, Instagram, Pinterest</strong> — for social integrations and share buttons.</li><li><strong>Payment providers or platform payment flows</strong> — when you open payment pages or complete transactions.</li></ul><p>We do <strong>not</strong> control these third-party cookies.<br> You can review their policies directly:</p><ul><li><a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a></li><li><a href="https://policies.google.com/technologies/ads" target="_blank" rel="noreferrer">Google Advertising Privacy &amp; Terms</a></li><li><a href="https://stripe.com/privacy" target="_blank" rel="noreferrer">Stripe Privacy Center</a></li><li><a href="https://telegram.org/privacy" target="_blank" rel="noreferrer">Telegram Privacy Policy</a></li><li><a href="https://privacycenter.instagram.com/policy" target="_blank" rel="noreferrer">Meta (Instagram) Privacy Policy</a></li><li><a href="https://www.facebook.com/privacy/policies/cookies/" target="_blank" rel="noreferrer">Meta Cookies Policy</a></li><li><a href="https://policy.pinterest.com/en/privacy-policy" target="_blank" rel="noreferrer">Pinterest Privacy Policy</a></li></ul><hr><h2 id="_4-managing-cookies" tabindex="-1">4. Managing Cookies <a class="header-anchor" href="#_4-managing-cookies" aria-label="Permalink to &quot;4. Managing Cookies&quot;">​</a></h2><p>You can manage or delete cookies as you wish:</p><ul><li><strong>Browser settings</strong> — Most browsers let you refuse or delete cookies.</li><li><strong>Incognito / Private mode</strong> — Opens a session that automatically deletes cookies after closing.</li><li><strong>Opt-out tools</strong> — Some analytics services (e.g., Google Analytics) provide opt-out options.</li><li><strong>TickerForge consent banner</strong> — You can accept or reject optional analytics and advertising tracking when the banner is shown.</li></ul><blockquote><p>Note: Disabling essential cookies may affect the site’s functionality.</p></blockquote><hr><h2 id="_5-consent" tabindex="-1">5. Consent <a class="header-anchor" href="#_5-consent" aria-label="Permalink to &quot;5. Consent&quot;">​</a></h2><p>When you first visit TickerForge, a consent notice may appear explaining that we use cookies and similar tracking technologies.<br> Optional analytics and advertising pixels, including Google Analytics and Meta Pixel, are loaded only after you accept optional tracking where the banner is available.<br> If you reject optional tracking, we will not intentionally load those optional pixels in your browser, but essential first-party functionality and operational events may still run.</p><p>You can withdraw or change your choice by clearing site data/cookies in your browser and revisiting the site.</p><hr><h2 id="_6-updates-to-this-cookie-policy" tabindex="-1">6. Updates to This Cookie Policy <a class="header-anchor" href="#_6-updates-to-this-cookie-policy" aria-label="Permalink to &quot;6. Updates to This Cookie Policy&quot;">​</a></h2><p>We may update this Cookie Policy from time to time.<br> Updates will be posted on this page with an updated “Last updated” date.<br> Continued use of our website after such updates constitutes your acceptance of the revised Policy.</p><hr><h2 id="_7-contact-us" tabindex="-1">7. Contact Us <a class="header-anchor" href="#_7-contact-us" aria-label="Permalink to &quot;7. Contact Us&quot;">​</a></h2><p>If you have any questions about this Cookie Policy or how we use cookies, contact us at:</p><p><strong>Email:</strong> <a href="mailto:privacy@ticker-forge.com" target="_blank" rel="noreferrer">privacy@ticker-forge.com</a></p>',35)]))}const g=o(r,[["render",s]]);export{u as __pageData,g as default};
